    vals = vals.reshape(count, 4)
    return count, steps, dt, vals


def simulate(count, steps, dt, vals):
    pos0 = np.ascontiguousarray(vals[:, 0:2], dtype=np.float32)
    vel0 = np.ascontiguousarray(vals[:, 2:4], dtype=np.float32)
    if steps == 0:
        return pos0, vel0

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    pos_buf = device.create_buffer_with_data(data=pos0.tobytes(), usage=storage)
    vel_buf = device.create_buffer_with_data(data=vel0.tobytes(), usage=storage)
    acc_buf = device.create_buffer(size=count * 8, usage=storage)
    params = np.zeros(4, dtype=np.uint8).view(np.uint8)
    pbytes = np.array([count], dtype=np.uint32).tobytes() + np.array([dt], dtype=np.float32).tobytes() + b"\0" * 8
    param_buf = device.create_buffer_with_data(
        data=pbytes, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST
    )

    module = device.create_shader_module(code=SHADER)
    bgl = device.create_bind_group_layout(entries=[
        {"binding": 0, "visibility": wgpu.ShaderStage.COMPUTE,
         "buffer": {"type": wgpu.BufferBindingType.uniform}},
        {"binding": 1, "visibility": wgpu.ShaderStage.COMPUTE,
         "buffer": {"type": wgpu.BufferBindingType.storage}},
        {"binding": 2, "visibility": wgpu.ShaderStage.COMPUTE,
         "buffer": {"type": wgpu.BufferBindingType.storage}},
        {"binding": 3, "visibility": wgpu.ShaderStage.COMPUTE,
         "buffer": {"type": wgpu.BufferBindingType.storage}},
    ])
    layout = device.create_pipeline_layout(bind_group_layouts=[bgl])
    accel = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "accelerate"})
    integ = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "integrate"})
    bind = device.create_bind_group(layout=bgl, entries=[
        {"binding": 0, "resource": {"buffer": param_buf, "offset": 0, "size": 16}},
        {"binding": 1, "resource": {"buffer": pos_buf, "offset": 0, "size": count * 8}},
        {"binding": 2, "resource": {"buffer": vel_buf, "offset": 0, "size": count * 8}},
        {"binding": 3, "resource": {"buffer": acc_buf, "offset": 0, "size": count * 8}},
    ])

    groups = (count + 63) // 64
    # one submission per step keeps each dispatch's work bounded
    for _ in range(steps):
        enc = device.create_command_encoder()
        p = enc.begin_compute_pass()
        p.set_bind_group(0, bind)
        p.set_pipeline(accel)
        p.dispatch_workgroups(groups)
        p.set_pipeline(integ)
        p.dispatch_workgroups(groups)
        p.end()
        device.queue.submit([enc.finish()])

    pos = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32).reshape(count, 2)
    vel = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32).reshape(count, 2)
    return pos, vel


def fmt(x):
    s = f"{x:.6f}"
    if s.startswith("-") and float(s) == 0.0:
        s = s[1:]
    return s


def main():
    count, steps, dt, vals = read_input(sys.argv[1])
    pos, vel = simulate(count, steps, dt, vals)
    pos = pos.astype(np.float64)
    vel = vel.astype(np.float64)
    center = pos.mean(axis=0)
    mom = vel.sum(axis=0)
    kinetic = ((vel * vel).sum(axis=1) / 2).sum()
    spread = np.sqrt(((pos - center) ** 2).sum(axis=1).mean())
    print(f"CENTER {fmt(center[0])} {fmt(center[1])}")
    print(f"MOMENTUM {fmt(mom[0])} {fmt(mom[1])}")
    print(f"KINETIC {fmt(kinetic)}")
    print(f"SPREAD {fmt(spread)}")


if __name__ == "__main__":
    main()
